import {QUESTIONS} from './questions.js';
import {KEY,createAttempt,validAttempt,upgradeAttempt,score,breakdown,answer,advance,shareData,readShare} from './engine.js';
const app=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let attempt=null,storageError='',page='home';
const question=id=>QUESTIONS.find(q=>q.id===id);
function read(){try{const raw=localStorage.getItem(KEY);if(!raw)return null;const stored=JSON.parse(raw),a=upgradeAttempt(stored);if(!validAttempt(a))throw Error('invalid');if(a!==stored){localStorage.setItem(KEY+':previous-bank',raw);localStorage.setItem(KEY,JSON.stringify(a));}return a;}catch{storageError='Saved attempt could not be read. This browser cannot safely start a new attempt. Check that site storage is available.';return null;}}
function save(a){localStorage.setItem(KEY,JSON.stringify(a));attempt=a;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';setTimeout(()=>el.style.display='none',4000);}
function remaining(){const n=Math.max(0,(attempt?.unlockAt??0)-Date.now());return new Date(n).toISOString().slice(11,19);}
function clock(){document.querySelectorAll('[data-timer]').forEach(el=>el.textContent=remaining());if(attempt&&Date.now()>=attempt.unlockAt)document.querySelectorAll('[data-expiry]').forEach(el=>{el.textContent='A new attempt is available';});}
function cooldown(){return attempt&&Date.now()<attempt.unlockAt?`<span data-expiry>Next attempt in <strong class="cooldown" data-timer>${remaining()}</strong></span>`:'A new attempt is available';}
function navigate(next){page=next;render();window.scrollTo({top:0,behavior:'instant'});}
function home(){
 const locked=attempt&&Date.now()<attempt.unlockAt;
 app.innerHTML=`${attempt?.bankUpdated?'<div class="banner">Question bank updated to encounter mechanics only. Your previous round has been replaced with new questions; the original hourly cooldown is unchanged.</div>':''}<section class="hero"><div class="hero-copy"><div class="eyebrow">THE VLOXX CM / LCM KNOWLEDGE CHECK</div><h1>ALL DAMAGE.<br><em>NO IDEA?</em></h1><p class="intro">Your rotation is immaculate. But can you soak a green?<br>Fifteen questions. Three choices. One correct answer.<br>Time to find out what you actually know.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><img src="assets/pleasure-pain.png" alt=""><span class="floating a">MECHANICS &gt; METERS</span><span class="floating b">YES, YOU STILL HAVE TO MOVE.</span></div></section>
 <div class="stats"><div class="stat"><strong>100</strong><span>questions in the bank</span></div><div class="stat"><strong>15</strong><span>questions per attempt</span></div><div class="stat"><strong>60 MIN</strong><span>between new attempts</span></div></div>
 <section class="start-panel"><div><h3>${attempt&&!attempt.completedAt?'Your pull is still alive.':locked?'That’s your pull for this hour.':'Ready for the mechanics check?'}</h3><p class="small">${attempt?cooldown():'A balanced mix of all phases, greens and resource mechanics. Answers and explanations appear after every choice.'}</p></div><div>${attempt&&!attempt.completedAt?`<button id="resume">Resume question ${attempt.index+1} <span>↗</span></button>${!locked?'<button class="secondary" id="fresh">New attempt</button>':''}`:locked?'<button id="results">View your results ↗</button>':`<form id="start-form"><label for="name">Your in-game name <span>(optional, visible in shared scores)</span></label><div class="form-row"><input id="name" name="name" maxlength="40" placeholder="DPS monkey.1234" autocomplete="nickname" value="${esc(attempt?.name??'')}"><button type="submit">Start the check <span>↗</span></button></div></form>`}${storageError?`<p class="error">${esc(storageError)}</p>`:''}</div></section>
 <div class="notes"><p>Encounter mechanics only: targeting, green soaks, attack behaviour and CM/LCM differences. Based on the mechanics guide and log checks through 19 Oct 2026.</p><p>Browser-saved cooldown. Clearing storage or changing browsers bypasses it. Shared scores are self-reported.</p></div>
 <div class="numberline">THE RULES &nbsp; / &nbsp; No answer changes. No repeats within a round. Refreshing resumes your attempt. Cooldown starts when you begin.</div>`;
 document.querySelector('#start-form')?.addEventListener('submit',e=>{e.preventDefault();start(document.querySelector('#name').value);});
 document.querySelector('#resume')?.addEventListener('click',()=>navigate('quiz'));
 document.querySelector('#results')?.addEventListener('click',()=>navigate('results'));
 document.querySelector('#fresh')?.addEventListener('click',()=>start(attempt.name));
}
async function withLock(fn){if(!navigator.locks){storageError='This browser does not support safe cross-tab attempts. Use a current browser over HTTPS or localhost.';render();return;}await navigator.locks.request(KEY,async()=>{try{storageError='';attempt=read();if(storageError){render();return;}await fn();}catch{storageError='Your attempt could not be saved. No new answer was accepted. Check that browser storage is enabled, then reload.';attempt=read();render();}});}
async function start(name){await withLock(()=>{if(attempt&&Date.now()<attempt.unlockAt){navigate(attempt.completedAt?'results':'quiz');return;}const fresh=createAttempt(name);save(fresh);navigate('quiz');});}
function quiz(){if(!attempt){home();return;}if(attempt.completedAt){results();return;}const item=attempt.items[attempt.index],q=question(item.id),answered=item.answer!==null,correct=item.answer===0;
 app.innerHTML=`<section class="quiz"><div class="quiz-top"><span>QUESTION <strong>${String(attempt.index+1).padStart(2,'0')}</strong> / 15</span><span>${esc(attempt.name)} <span class="dot">·</span> <strong>${score(attempt)} correct</strong></span></div><div class="progress" role="progressbar" aria-label="Questions answered" aria-valuemin="0" aria-valuemax="15" aria-valuenow="${attempt.items.filter(i=>i.answer!==null).length}"><div style="width:${attempt.items.filter(i=>i.answer!==null).length/15*100}%"></div></div><div class="question-meta"><span class="pill">${esc(q.category)}</span><span class="small">${/LCM|CM/.test(q.prompt)?'Read the mode carefully':'CM + LCM'}</span></div><h1 class="question-title" tabindex="-1">${esc(q.prompt)}</h1><div class="choices">${item.order.map((canonical,i)=>`<button class="choice ${answered?(canonical===0?'correct':canonical===item.answer?'wrong':''):''}" data-answer="${i}" ${answered||storageError?'disabled':''}><span class="letter">${'ABC'[i]}</span><span class="choice-text">${esc(q.choices[canonical])}${answered&&canonical===0?'<span class="sr-only"> — Correct answer</span>':''}${answered&&canonical===item.answer&&canonical!==0?'<span class="sr-only"> — Your incorrect answer</span>':''}</span>${answered&&canonical===0?`<img class="answer-icon" src="assets/${correct?'pleasure-pain':'gigachad'}.png" alt="${correct?'Vloxx Pleasure/Pain — correct':'Vloxx Gigachad — here is the correct answer'}">`:''}</button>`).join('')}</div>${answered?`<div class="feedback ${correct?'':'bad'}" role="status"><strong>${correct?'Correct. You may continue parsing.':'Incorrect. Vloxx has a few notes.'}</strong><p><b>Correct answer: ${esc(q.choices[0])}</b><br>${esc(q.explanation)}</p><a href="${q.source}#${q.section}" target="_blank" rel="noopener">Read the mechanics guide ↗</a></div>`:''}${storageError?`<p class="error" role="alert">${esc(storageError)}</p>`:''}<div class="quiz-bottom"><span class="small">${answered?'Answer saved. No take-backs.':'Choose A, B or C. Your first answer is final.'}<br>Refresh any time — your progress is saved.</span>${answered?`<button id="next">${attempt.index===14?'See my results':'Next question'} <span>→</span></button>`:'<span class="small">KEYBOARD: A / B / C</span>'}</div></section>`;
 document.querySelectorAll('[data-answer]').forEach(el=>el.addEventListener('click',()=>choose(Number(el.dataset.answer),item.id)));
 document.querySelector('#next')?.addEventListener('click',()=>withLock(()=>{if(!attempt)return navigate('home');if(attempt.items[attempt.index].id!==item.id)return navigate(attempt.completedAt?'results':'quiz');const updated=structuredClone(attempt);if(advance(updated)){save(updated);navigate(updated.completedAt?'results':'quiz');}}));
}
async function choose(index,id){await withLock(()=>{if(!attempt)return navigate('home');if(attempt.items[attempt.index].id!==id||attempt.completedAt)return navigate(attempt.completedAt?'results':'quiz');const updated=structuredClone(attempt);if(answer(updated,index)){delete updated.bankUpdated;save(updated);}render();document.querySelector('#next')?.focus();});}
function rank(n){return n>=13?'Mechanics enjoyer.':n>=10?'There’s a raider in there.':n>=7?'A few pulls from ready.':'The golem never taught you this.';}
function topicsHtml(values){return values.map(t=>`<div class="topic"><div class="topic-head"><span>${esc(t.category)}</span><strong>${t.correct} / ${t.total}</strong></div><div class="topic-bar"><div style="width:${t.correct/t.total*100}%"></div></div></div>`).join('');}
function results(shared=null){if(!shared&&!attempt?.completedAt)return home();const n=shared?shared.score:score(attempt),name=shared?shared.name:attempt.name,values=shared?['Greens','Resources','Staff','Spear','Endgame'].map((category,i)=>({category,correct:shared.topics[i],total:3})):breakdown(attempt);
 app.innerHTML=`${shared?'<div class="banner">SHARED RESULT · Self-reported score. This link is editable and is not a verified qualification.</div>':''}<div class="eyebrow">${shared?'A RAIDER’S REPORT CARD':'PULL COMPLETE · RESULTS SAVED'}</div><div class="result-layout"><section class="score-card"><img src="assets/${n>=10?'pleasure-pain':'gigachad'}.png" alt="Vloxx"><div class="big-number">${n}<small>/15</small></div><h3>${rank(n)}</h3><p class="small">${esc(name)} <span class="dot">·</span> ${Math.round(n/15*100)}% correct</p><span class="pill">CM + LCM MECHANICS CHECK</span></section><section><h2>MECHANICS.<br>UNDER THE MICROSCOPE.</h2><p class="small">Three questions per topic. Here’s where the knowledge held up.</p>${topicsHtml(values)}${shared?`<div class="actions"><button id="own">Take your own check ↗</button></div><p class="small">Completed ${esc(new Date(shared.date).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'}))}</p>`:`<div class="actions"><button id="share">Share score ↗</button><button class="secondary" id="copy">Copy link</button></div><div id="share-fallback"></div><p class="small" style="margin-top:13px">Shared links show your name, score and topic breakdown. Scores are self-reported.</p><div class="notice small">${cooldown()}<br>Cooldown runs from the start of your attempt. <a href="./" id="home">Back to start</a></div>`}</section></div>${!shared?`<section class="review"><h2>YOUR ANSWER REVIEW</h2><p class="small">Open a question to see your answer, the correct answer and why.</p>${attempt.items.map((i,j)=>{const q=question(i.id);return `<details><summary><span class="${i.answer===0?'good':'bad'}">${i.answer===0?'✓':'×'}</span><span>${j+1}. ${esc(q.prompt)}</span></summary><p>Your answer: <span class="${i.answer===0?'good':'bad'}">${esc(q.choices[i.answer])}</span><br>Correct answer: <span class="good">${esc(q.choices[0])}</span><br>${esc(q.explanation)}<br><a href="${q.source}#${q.section}" target="_blank" rel="noopener">Guide ↗</a></p></details>`;}).join('')}</section>`:''}`;
 document.querySelector('#home')?.addEventListener('click',e=>{e.preventDefault();navigate('home');});
 document.querySelector('#own')?.addEventListener('click',()=>{history.replaceState(null,'',location.pathname+location.search);navigate('home');});
 document.querySelector('#copy')?.addEventListener('click',copyLink);
 document.querySelector('#share')?.addEventListener('click',async()=>{const url=shareUrl();if(navigator.share){try{await navigator.share({title:'Vloxx Mechanics Check',text:`${attempt.name} scored ${score(attempt)}/15 on Vloxx mechanics.`,url});}catch(e){if(e.name!=='AbortError')copyLink();}}else copyLink();});
}
function shareUrl(){const url=new URL(location.href);url.hash='score='+encodeURIComponent(JSON.stringify(shareData(attempt)));return url.href;}
async function copyLink(){try{await navigator.clipboard.writeText(shareUrl());toast('Score link copied. Send it to your squad.');}catch{document.querySelector('#share-fallback').innerHTML=`<div class="share-url"><label for="share-url">Copy your score link</label><input id="share-url" readonly value="${esc(shareUrl())}"></div>`;const input=document.querySelector('#share-url');input.focus();input.select();}}
function render(){const shared=readShare(location.hash);if(shared===false){app.innerHTML='<section class="empty"><div class="eyebrow">INVALID SCORE LINK</div><h2>THIS LINK MISSED ITS GREEN.</h2><p class="small">The result data is incomplete or invalid.</p><a class="button" href="./">Back to the check</a></section>';return;}if(shared)return results(shared);if(page==='quiz')quiz();else if(page==='results')results();else home();clock();}
document.addEventListener('keydown',e=>{if(page!=='quiz'||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;const index='abc'.indexOf(e.key.toLowerCase());if(index>=0){const button=document.querySelector(`[data-answer="${index}"]`);if(button&&!button.disabled){e.preventDefault();button.click();}}});
window.addEventListener('storage',e=>{if(e.key===KEY){attempt=read();if(!attempt)page='home';render();}});
window.addEventListener('hashchange',render);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){attempt=read();render();}});
attempt=read();render();let wasLocked=!!attempt&&Date.now()<attempt.unlockAt;setInterval(()=>{const locked=!!attempt&&Date.now()<attempt.unlockAt;if(wasLocked&&!locked&&page==='home')render();wasLocked=locked;clock();},1000);
